#include <iostream>
#include <cstring>

int main() {
    // 1. Duyệt mảng 1 chiều bằng con trỏ tịnh tiến
    int arr[5] = {10, 20, 30, 40, 50};
    for (int *p = arr; p <= arr + 4; ++p) {
        std::cout << *p << " ";
    }
    std::cout << "\n";

    // 2. Con trỏ xâu và phân biệt gán địa chỉ vs sao chép nội dung
    const char *src = "UET_Cpp";
    const char *alias = src; // Cùng trỏ một vùng nhớ

    char *deep_copy = new char[30];
    std::strcpy(deep_copy, src); // Cấp phát độc lập và sao chép byte

    std::cout << alias << " " << deep_copy << "\n";
    std::cout << (alias == src ? 1 : 0) << " ";
    std::cout << (deep_copy == src ? 1 : 0) << "\n";

    delete[] deep_copy;
    return 0;
}

#include <iostream>

int main() {
    // 1. Phẳng hoá ma trận 2x3 thông qua con trỏ float*
    constexpr int ROWS = 2;
    constexpr int COLS = 3;
    float matrix[ROWS][COLS] = {
        {1.5f, 2.5f, 3.5f},
        {4.5f, 5.5f, 6.5f}
    };

    float *p = &matrix[0][0]; // Hoặc (float*)matrix
    // Truy cập phần tử hàng 1, cột 2 qua con trỏ: *(p + 1*3 + 2)
    std::cout << *(p + 1 * COLS + 2) << "\n";

    // 2. Mảng con trỏ lưu trữ các xâu ký tự (ragged array)
    const char *lines[3] = {
        "Row 0",
        "Second row is longer",
        "End"
    };

    for (int i = 0; i < 3; ++i) {
        std::cout << lines[i] << "\n";
    }

    return 0;
}
